mapper.select:
SELECT s.id, s.movie_id, m.name AS movie_name, s.hall_id, h.name AS hall_name, h.location, s.start_time, s.end_time, s.price, s.language_version, s.status FROM session s JOIN movie m ON m.id = s.movie_id JOIN hall h ON h.id = s.hall_id
AND m.name LIKE CONCAT('%', #{movieName}, '%')
AND h.name = #{hallName}
AND h.location LIKE CONCAT('%', #{location}, '%')
AND s.start_time >= #{startTime}
AND s.start_time < DATE_ADD(#{endTime}, INTERVAL 1 DAY)
AND s.status = #{status}
ORDER BY s.start_time DESC

SELECT COUNT(*) FROM session
WHERE hall_id = #{hallId}
  AND status != 2
AND start_time < #{endTime}
  AND end_time > #{startTime}

SELECT COUNT(*) FROM session
WHERE movie_id = #{id}
  AND status = 1
